insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-19', 'k-central', 2, 'ما الوسيط للقيم: 3، 3، 5، 8، 9، 12، 15، 20؟', '["8","8.5","9","10"]'::jsonb, 1, 'عدد القيم زوجي (8 قيم)، فالوسيط = متوسط القيمتين الوسطيتين (8 و9) = 8.5.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-20', 'k-central', 3, 'متوسط درجات 10 طلاب 12 درجة. إذا أضيفت درجة طالب جديد فأصبح المتوسط 13، فما درجة الطالب الجديد؟', '["13","20","23","25"]'::jsonb, 2, 'مجموع العشرة = 120، والمجموع الجديد = 13 × 11 = 143، فدرجة الطالب = 143 − 120 = 23.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-21', 'k-central', 3, 'متوسط 5 قيم هو 20. إذا حُذفت قيمة مقدارها 40، فما متوسط القيم الأربع المتبقية؟', '["12","15","16","18"]'::jsonb, 1, 'المجموع الأصلي = 100، وبعد الحذف = 60، والمتوسط = 60 ÷ 4 = 15.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-22', 'k-central', 2, 'القيم: 7، 7، 9، 9، 12. هذا التوزيع:', '["عديم المنوال","أحادي المنوال","ثنائي المنوال","متعدد المنوال"]'::jsonb, 2, 'القيمتان 7 و9 تكررت كل منهما مرتين بأعلى تكرار، فالتوزيع ثنائي المنوال.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-23', 'k-central', 3, 'في توزيع درجات: المتوسط 70 والانحراف المعياري 5. أي مدى يقع فيه نحو 68% من الدرجات في التوزيع الطبيعي؟', '["من 60 إلى 80","من 65 إلى 75","من 70 إلى 75","من 55 إلى 85"]'::jsonb, 1, 'في التوزيع الطبيعي يقع نحو 68% من القيم ضمن انحراف معياري واحد حول المتوسط: 70 ± 5 أي من 65 إلى 75.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-24', 'k-central', 2, 'إذا أُضيفت 5 درجات لكل طالب في الصف، فإن الانحراف المعياري للدرجات:', '["يزيد 5","ينقص 5","لا يتغير","يتضاعف"]'::jsonb, 2, 'إضافة مقدار ثابت لجميع القيم تزيح التوزيع كاملاً دون تغيير تباعد القيم عن بعضها، فالتشتت يبقى كما هو.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
